! ls $S/claims 2>/dev/null | grep -q "issue20" && ! test -e $S/runs/builder-20.json && ! tmux list-windows -t crew-campaign-{run_id} -F "#{window_name}" | grep -qx builder-20 || exit 1
$C lead handoff builder build "#20" $P | grep -x "crew: solo item; skip builder handoff; post findings/CI on the PR for the owner's session" || exit 1
echo '[{"number":20,"labels":[{"name":"crew:ready"},{"name":"crew:solo"}],"assignees":[{"login":"owner"}]}]' > "$G/issue-list-label-crew:ready.json"
$C poll --once $P | grep -x "crew: poll: issue-assigned -> builder #20" && $C route $P >/dev/null || exit 1
test "$(n issue-assigned 20)" = 0 && ! test -e $S/inbox/builder-lead.jsonl && ! ls $S/runs/builder-* 2>/dev/null && echo "issue-assigned #20 consumed; no builder run, claim or builder-lead message" || exit 1
$C spawn builder --issue 3 $P --timeout 10 | grep "^crew: started builder-3 " && CREW_POOL=builder $C kill builder-3 $P >/dev/null

