$V 7 $(h 7) sg=none nolabel=crew:express label=crew:solo ilabel=crew:solo ci=PENDING && $V 8 $(h 8) sg=none nolabel=crew:express label=crew:solo ilabel=crew:solo ci=PENDING "engine=codex gpt-6.1-sol medium" || exit 1
out=$($C poll --once $P) || exit 1; echo "$out"
echo "$out" | grep -qx "crew: poll: new-head -> reviewer #7 $(h 7)" && echo "$out" | grep -qx "crew: poll: new-head -> reviewer #8 $(h 8)" || exit 1
tg && $C route $P >/dev/null && pool >/dev/null; a=$(rv reviewer-7-r1-review); b=$(rv reviewer-8-r1-review); echo "reviewer-7-r1-review: $a (owner session claude-code)"; echo "reviewer-8-r1-review: $b (owner session codex)"
test "$a" = "codex $(h 7)" && test "${b% *}" = claude-code && kr 8

C="python3 {source}/cli/mdstack"; P="--project $CREW_PROJECT"; S={state_dir}/campaign__sandbox-{run_id}; G={state_dir}/gh; O={state_dir}/../origin.git; R={state_dir}/../repo; F={source}/dev/tests/scripts/fixtures/campaign; V="python3 $F/a17/view.py"; PATH=$F/a14:$PATH; T="--grace 0 --interval 0 --timeout 10"
