rv() { python3 -c "import json,sys; r=json.load(open(sys.argv[1])); print(r['engine'], r['head'])" $S/runs/$1.json; }
H=$(h 7); vm="<!-- crew:v1 role=reviewer-validator pass=verdict pr=7 sha=$H round=1 verdict=changes -->"; skip="post findings/CI on the PR for the owner's session"
$V 7 $H sg=none nolabel=crew:express label=crew:solo ilabel=crew:solo ci=FAILURE; $C poll --once $P | grep -x "crew: poll: ci-failed -> builder #7 $H" && $C route $P >/dev/null || exit 1
test "$(n ci-failed 7)" = 1 && ! test -e $S/inbox/builder-lead.jsonl && echo "ci-failed #7 stays queued for coordinator pickup; builder-lead inbox empty" || exit 1
for k in fix ci-red merge-up; do $C lead handoff builder $k "#7" $P | grep -x "crew: solo item; skip builder handoff; $skip" || exit 1; done
$C send builder-7 fix "#7" $P | grep -x "crew: solo item; skip builder delivery; $skip" || exit 1
out=$($C spawn builder --issue 17 --pr 7 --pass fix $P --timeout 10); rc=$?; echo "spawn fix #7 exit $rc: $out"; test $rc = 1 || exit 1
v=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['verdict'])" $S/runs/reviewer-7-r1-review.json); mkdir -p $S/verdicts; printf '%s\nsection x\n' "$vm" > $v
echo "done: #7 $H review changes" >> $S/status/reviewer-7-r1-review.status; printf '{"reason":"status","window":"reviewer-7-r1-review","line":"done: #7 %s review changes"}\n' $H >> $S/wake/queue.jsonl
$V 7 $H sg=none nolabel=crew:express label=crew:solo ilabel=crew:solo ci=FAILURE "review=CHANGES_REQUESTED|$vm"; $C route $P >/dev/null && pool | grep -x "crew: killed reviewer-7-r1-review" && pool >/dev/null || exit 1
$C lead handoff builder fix "#7" $P | grep -x "crew: solo item; skip builder handoff; $skip" && ! ls $S/runs/builder-* 2>/dev/null && ! ls $S/claims | grep -q "^builder-" && echo "changes verdict on the PR; no crew builder run or claim"

