H=$(h 7); vs="$(for k in review validate verdict; do printf '<!-- crew:v1 role=reviewer-validator pass=%s pr=7 sha=%s base=%s round=2 verdict=pass -->\n' $k $H $(cat $G/base); done)"
miss() { w=$1; shift; $V 7 $H label=crew:solo ilabel=crew:solo "$@" && out=$($C train check 7 $P); rc=$?; echo "miss [${*%%|*}] exit $rc: $(echo "$out" | grep "status=blocked" | sed "s/^gate pr=[0-9]* sha=[0-9a-f]* //" | tr '\n' ' ')"; test $rc = 1 && echo "$out" | grep -q -- "$w"; }
miss 'missing formal passing review/validate/verdict at head' nolabel=crew:express sg=none || exit 1
miss 'name=express status=blocked reason="crew lane (item flavor standard (express-ineligible)): drop crew:express"' override || exit 1
miss 'name=ci status=blocked' nolabel=crew:express sg=none ci=FAILURE "review=APPROVED|$vs" || exit 1
miss 'state tag crew:hold' nolabel=crew:express sg=none label=crew:hold "review=APPROVED|$vs" || exit 1
$V 7 $H sg=none nolabel=crew:express label=crew:solo ilabel=crew:solo "review=APPROVED|$vs"; $C train check 7 $P | grep -o "name=verdict status=pass.*" || exit 1
b=$($C train build 7 $P $T) && k=$(echo "$b" | sed -n "s/^train n=\([0-9]*\) .*ci=pass$/\1/p") && test -n "$k" || exit 1
